# window: Hash seq => message; out: Thread::Queue (ordered handoff)
def accept(seq, msg)
  @mutex.synchronize do
    @window[seq] = msg                    # duplicates policy: keep last
    while (m = @window.delete(@expected))
      @out.push(m)                        # Queue preserves push order
      @expected += 1
    end
    trim_and_expire(@window)              # capacity + gap policy
  end
end
